loop(request):
  ctx  = build_context(twin_state, rag_retrieve(request))
  plan = planner(ctx, request)          # sequence of bounded tools
  for step in plan:
    obs = call_tool(step)               # read/simulate only
    ctx = ctx + obs
    if planner.replan(ctx): plan = planner(ctx)
  ans = compose(ctx)                    # answer + citations + UQ
  if ans.has_side_effect: submit_to_L4(ans.proposal)
  return ans

def plan_and_act(request, ctx, budget):
    trace = []
    for step in range(budget.max_steps):
        thought, call = planner(ctx, request, trace)
        if call is None:                 # planner ready to answer
            return compose(ctx, trace)
        if not schema_valid(call):       # bounded action check
            trace.append(error(call)); continue
        obs = execute(call)              # read / simulate / propose
        trace.append((thought, call, obs))
        ctx = update(ctx, obs)
    return compose(ctx, trace, note='budget exhausted')

compose_with_citations(trace):
  answer = draft(trace)
  for claim in factual_claims(answer):
     src = match(claim, trace.provenance)
     if src: annotate(claim, src)
     elif is_inference(claim): label(claim, 'inference (unverified)')
     else: drop_or_rewrite(claim)
  assert coverage(answer) == 1.0    # no bare factual claim
  return answer

TEMPLATE plasma_copilot v7:
  [ROLE]    You advise on {machine}. You propose; you never actuate.
  [CANON]   {frozen_numbers}   # cited, never invented
  [RULES]   stay in envelope; cite every fact; label inference;
            no economics; no net-gain claim pre-FOAK; refuse if unsafe
  [TOOLS]   {bounded_tool_schemas}
  [STATE]   {twin_state_summary}
  [EVIDENCE]{retrieved_chunks}
  [TASK]    {question}
  [OUTPUT]  {answer, citations[], uncertainty, proposal?}

authorize(proposal, operator, state):
  if not schema_valid(proposal):        return DENY('malformed')
  if not envelope_contains(state+proposal): return DENY('envelope')
  if not operator.authority >= proposal.level: return DENY('authority')
  if rate_limit_exceeded(proposal):     return DENY('rate')
  if machine_mode incompatible:         return DENY('mode')
  if proposal.side_effect and not human_confirmed: return HOLD
  return FORWARD_TO_L1(proposal)        # L1 still owns execution

envelope_contains(state, proposal):
  s' = predict(state, proposal)          # twin/reduced model
  for c in constraints:                   # breeder or burner set
     if not c.satisfied(s'):
        return (False, c.name, c.margin(s'))
  return (True, None, min_margin(s'))

decide(request, state, evidence):
  if would_exit_envelope(request): return REFUSE('envelope', fix)
  if exceeds_authority(request):   return ESCALATE('authority')
  if grounding(evidence) < min:    return REFUSE('insufficient evidence')
  if stale(state) and time_critical(request): return REFUSE('stale state')
  if implies_forbidden_claim(request): return REFUSE('cannot claim')
  return ANSWER

